<?php
 namespace QQWorld\Captcha\Test\Constraint; use QQWorld\Customer\Test\Page\CustomerAccountCreate; use QQWorld\Mtf\Constraint\AbstractConstraint; class AssertCaptchaFieldOnRegisterForm extends AbstractConstraint { public function processAssertRegisterForm(CustomerAccountCreate $createAccountPage) { \PHPUnit_Framework_Assert::assertTrue( $createAccountPage->getRegisterForm()->isVisibleCaptcha(), 'Captcha image is not displayed on the storefront account register page.' ); \PHPUnit_Framework_Assert::assertTrue( $createAccountPage->getRegisterForm()->isVisibleCaptchaReloadButton(), 'Captcha reload button is not displayed on the storefront account register page.' ); } public function toString() { return 'Captcha and reload button are displayed on the storefront account register page.'; } } 